{
  "PROP-6a4369e9-post-002": {
    "property_id": "PROP-6a4369e9-post-002",
    "audit_result": {
      "property_id": "PROP-6a4369e9-post-002",
      "classification": "vulnerability",
      "code_path": "beacon-chain/sync/validate_data_column.go::validateDataColumn::L37-38",
      "proof_trace": "Self-peer bypass at L37-38 accepts own messages without any REJECT checks. Local validator's data columns skip all 12 gossip requirements (field validity, KZG proofs, proposer signature, inclusion proofs, etc.) and return ValidationAccept immediately.",
      "attack_scenario": "Compromised local validator or malicious modification of validator client can broadcast invalid data columns (wrong KZG proofs, invalid signatures, incorrect subnets) which are auto-accepted by own node, bypassing all consensus validation. These invalid sidecars propagate to forkchoice/storage before detection.",
      "checklist_id": "PROP-6a4369e9-post-002"
    },
    "text": "After gossip validation acceptance, sidecar must have passed all REJECT checks in order.",
    "assertion": "forall sidecar: accepted(sidecar) => all_reject_checks_passed(sidecar) == true",
    "covers": "SG-006",
    "severity": "CRITICAL",
    "type": "post-condition"
  }
}

